INSERT INTO public.support_quick_replies VALUES ('7dbd27fc-a58c-438c-940f-b2fc1860f1b8', 'Looking into it', 'Hello {name}, thank you for telling us. We are looking into it now and will get back to you shortly.', NULL, '2026-10-14 13:18:37.501204+00');
INSERT INTO public.support_quick_replies VALUES ('a42fc677-71a7-46c1-8a2a-f802964cbc94', 'Try clock-in again', 'Hello {name}, please close Xtend completely, make sure Location, Camera and Notifications are allowed, stand outside in the open for a minute, then try to clock in again. Tell us here if it still does not work.', NULL, '2026-10-14 13:18:37.501204+00');
INSERT INTO public.support_quick_replies VALUES ('e0cf0ee3-841a-401b-807f-f26749e91a05', 'Fixed, try again', 'Hello {name}, this has been fixed on our side. Please try again now and let us know if anything is still wrong.', NULL, '2026-10-14 13:18:37.501204+00');
INSERT INTO public.support_quick_replies VALUES ('5d6d5b0b-4046-45fa-b935-038c8fddf46e', 'Store change done', 'Hello {name}, your store has been updated. Close and open Xtend again to see it.', NULL, '2026-10-14 13:18:37.501204+00');
INSERT INTO public.support_quick_replies VALUES ('60147483-1407-403d-bc53-544017219a95', 'Call your supervisor', 'Hello {name}, please call your supervisor about this today so they can sort it out with you directly.', NULL, '2026-10-14 13:18:37.501204+00');
INSERT INTO public.xm_policy_versions VALUES ('7a552e95-8209-4052-a391-41f71953b1f0', 'How X Metrics scores your work', 'X Metrics gives every merchandiser and marketer a monthly score from 0 to 100, from what you send from your stores. The weights and bands below are set by the office.
